"""Decision Models transport wrapper. Native distributions are never recalibrated."""
import argparse
import base64
import io
import json
from http.server import BaseHTTPRequestHandler, HTTPServer

def text(value):
    return value if isinstance(value, str) else json.dumps(value, ensure_ascii=False)

def images(body, maximum=4):
    refs = body.get("images", [])
    if not isinstance(refs, list) or len(refs) > maximum:
        raise ValueError("unsupported image count")
    from PIL import Image
    result = []
    for ref in refs:
        if not isinstance(ref, str) or not ref.startswith(("data:image/png;base64,", "data:image/jpeg;base64,", "data:image/webp;base64,")):
            raise ValueError("images must be PNG/JPEG/WebP base64 data URLs")
        raw = base64.b64decode(ref.split(",", 1)[1], validate=True)
        if len(raw) > 8_000_000:
            raise ValueError("image exceeds 8 MB")
        with Image.open(io.BytesIO(raw)) as image:
            if image.width * image.height > 16_000_000:
                raise ValueError("image exceeds 16 million pixels")
            result.append(image.convert("RGB"))
    return result

def serve(predict, model, port):
    class Handler(BaseHTTPRequestHandler):
        def send(self, status, value):
            data = json.dumps(value, ensure_ascii=False, allow_nan=False).encode()
            self.send_response(status)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)
        def do_GET(self):
            if self.path == "/health":
                self.send(200, {"status": "ok", "model": model})
            else:
                self.send(404, {"error": "not found"})
        def do_POST(self):
            if self.path not in ("/v1/systemone", "/v1/multimodal"):
                return self.send(404, {"error": "not found"})
            try:
                size = int(self.headers.get("Content-Length", "0"))
                if not 0 < size <= 48_000_000:
                    return self.send(413, {"error": "request exceeds limit"})
                body = json.loads(self.rfile.read(size))
                if not isinstance(body.get("questions"), dict) or not body["questions"]:
                    raise ValueError("questions must be a nonempty object")
                if self.path == "/v1/multimodal" and not body.get("images"):
                    raise ValueError("multimodal requires images")
                self.send(200, predict(body))
            except (ValueError, KeyError, TypeError) as exc:
                self.send(422, {"error": str(exc)})
            except Exception as exc:
                self.send(500, {"error": type(exc).__name__})
        def log_message(self, *args):
            pass
    # Single worker: native caches and hooks are serialized across requests.
    HTTPServer(("127.0.0.1", port), Handler).serve_forever()

def args():
    p = argparse.ArgumentParser()
    p.add_argument("--weights", required=True)
    p.add_argument("--port", type=int, required=True)
    p.add_argument("--device", default="cuda", choices=["cuda", "cpu", "mps"])
    p.add_argument("--base")
    p.add_argument("--host", default="127.0.0.1", choices=["127.0.0.1"])
    return p.parse_args()

def main():
    a = args()
    if a.device != "cuda" or not a.base:
        raise ValueError("Jev-Omni requires CUDA and a verified local Gemma base")
    import importlib.util
    from pathlib import Path
    import torch
    import transformers
    from transformers import AutoConfig, AutoProcessor
    def module(name, filename):
        spec = importlib.util.spec_from_file_location(name, Path(a.weights)/filename)
        value = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(value)
        return value
    loader = module("omni_text_loader", "load_model.py")
    native = module("omni_multimodal", "jev_omni.py")
    # Author multimodal assembly, with BH CPU-first placement to avoid an FP32 CUDA copy.
    decoder, head, _ = loader.load_model(a.weights, device="cpu")
    for layer in decoder.modules():
        if isinstance(layer, torch.nn.Linear):
            layer.weight.data = layer.weight.data.to(torch.bfloat16)
    decoder, head = decoder.to("cuda").eval(), head.to("cuda").eval()
    config = AutoConfig.from_pretrained(a.base, local_files_only=True)
    model = getattr(transformers, config.architectures[0]).from_pretrained(
        a.base, dtype=torch.bfloat16, device_map="cuda", local_files_only=True).eval()
    path, old = native._find_backbone(model)
    parent, _, name = path.rpartition(".")
    setattr(model.get_submodule(parent) if parent else model, name, decoder)
    del old
    torch.cuda.empty_cache()
    processor = AutoProcessor.from_pretrained(a.base, local_files_only=True)
    class CountingProcessor:
        def __init__(self):
            self.input_tokens = 0
        def apply_chat_template(self, *args, **kwargs):
            inputs = processor.apply_chat_template(*args, **kwargs)
            self.input_tokens += int(inputs["input_ids"].shape[1])
            return inputs
    counter = CountingProcessor()
    engine = native.JevOmni(model, head, counter, decoder, "cuda")
    def predict(body):
        import tempfile
        photos = images(body, maximum=1)
        answers, originals = {}, {}
        counter.input_tokens = 0
        with tempfile.TemporaryDirectory(prefix="dm-omni-") as tmp:
            media = None
            if photos:
                media = str(Path(tmp)/"image.png")
                photos[0].save(media)
            for qid, q in body["questions"].items():
                if q["type"] == "noul":
                    criteria = q.get("criteria") or {}
                    keys = ["no", "yes"]
                    rubric = {"no": criteria.get("false", "No"), "yes": criteria.get("true", "Yes")}
                elif q["type"] == "choice":
                    keys = list(q["criteria"])
                    rubric = {key: value or key for key, value in q["criteria"].items()}
                elif q["type"] == "score":
                    keys = [str(i) for i in range(len(q["criteria"]))]
                    rubric = dict(zip(keys, q["criteria"]))
                else:
                    raise ValueError("unsupported question type")
                # Preserve duplicate descriptions: author probabilities dict collapses duplicate keys.
                # Reject ambiguity rather than invent a distribution.
                options = [text(rubric[key]) for key in keys]
                if len(set(options)) != len(options):
                    raise ValueError("Jev-Omni requires distinct option descriptions")
                result = engine.predict(state=text(body["state"]),
                                        question=text(q["instructions"])+"\nRubric: "+json.dumps(rubric, ensure_ascii=False),
                                        options=options, media=media, modality="image" if media else "text")
                originals[qid] = result
                probs = [result["probabilities"][option] for option in options]
                if q["type"] == "noul":
                    answers[qid] = {"type": "noul", "noul": probs[1], "confidence": result["confidence"]}
                elif q["type"] == "choice":
                    answers[qid] = {"type": "choice", "choice": keys[result["prediction_index"]],
                                    "probabilities": dict(zip(keys, probs)), "confidence": result["confidence"]}
                else:
                    answers[qid] = {"type": "score", "score": sum(i*p for i, p in enumerate(probs)),
                                    "probabilities": dict(zip(keys, probs)), "legend": dict(zip(keys, options)),
                                    "confidence": result["confidence"]}
        return {"model": "jev-omni", "answers": answers, "native": originals, "usage": {"input_tokens": counter.input_tokens, "output_tokens": 0}}
    serve(predict, "jev-omni", a.port)

if __name__ == "__main__":
    main()
